begin
  select count(*) into n from wine_place_boundaries b join wine_places p on p.id=b.wine_place_id where p.canonical_key='italy.sardegna' and b.is_current and b.quality_status='VALIDATED';
  if n <> 1 then raise exception 'expected 1 current Sardegna region boundary, got %', n; end if;
  select b.bbox into bx from wine_place_boundaries b join wine_places p on p.id=b.wine_place_id where p.canonical_key='italy.sardegna' and b.is_current;
  if bx[1] < 8.1 or bx[2] < 38.8 or bx[3] > 9.9 or bx[4] > 41.3 then raise exception 'Sardegna region bbox escapes window: %', bx; end if;
end $$;

