insert into wine_place_boundaries (wine_place_id, source_snapshot_id, boundary_method, quality_status, display_geometry, label_point, bbox, source_feature_refs, generation_parameters, revision, is_current, reviewed_at)
select p.id, snap.id, 'GENERALIZED_FROM_OFFICIAL_SOURCE', 'VALIDATED', geom.g, extensions.ST_PointOnSurface(geom.g),
       array[extensions.ST_XMin(extensions.Box3D(geom.g)), extensions.ST_YMin(extensions.Box3D(geom.g)), extensions.ST_XMax(extensions.Box3D(geom.g)), extensions.ST_YMax(extensions.Box3D(geom.g))]::double precision[],
       '{"source":"ISTAT regione Molise"}'::jsonb, '{"engine":"istat-admin-region","simplify":"mapshaper 6%","holes":"dropped","coordinate_precision":5}'::jsonb,
       '20260907T000000Z', true, now()
from wine_places p, snap, geom where p.canonical_key = 'italy.molise';

do $$
declare n int; bx double precision[];
begin
  select count(*) into n from wine_place_boundaries b join wine_places p on p.id=b.wine_place_id where p.canonical_key='italy.molise' and b.is_current and b.quality_status='VALIDATED';
  if n <> 1 then raise exception 'expected 1 current Molise region boundary, got %', n; end if;
  select b.bbox into bx from wine_place_boundaries b join wine_places p on p.id=b.wine_place_id where p.canonical_key='italy.molise' and b.is_current;
  if bx[1] < 13.9 or bx[2] < 41.3 or bx[3] > 15.2 or bx[4] > 42.1 then raise exception 'Molise region bbox escapes window: %', bx; end if;
end $$;

commit;
